/**
 * @brief Resize value-use scratch storage after a loop transformation adds
 * values.
 *
 * @param ctx Compiler context owning the IR.
 * @param values Number of SSA values for which scratch space is required.
 */
static void grow_loop_uses(Ctx* ctx, size_t values) {
  OptimizerCtx* optimizer = &ctx->optimizer;

  if (values > optimizer->sizes.values) {
    TRY_REALLOC(optimizer->value_data, values * sizeof(*optimizer->value_data));
    optimizer->sizes.values = values;
  }
}

// AI generated by: Codex (GPT-6.2-sol)
