// Changes: Keep value-use storage valid when unrolling several loops in a
// function.
void optimizer_transform_loops(Ctx* ctx) {
  for (IrFunctionId fid = 0; fid < ctx->ir.functions.count; fid++) {
    IrFunction* fn = &ctx->ir.functions.data[fid];
    // Generated fast paths are outside this scan so they cannot be paired
    // again.
    size_t original_blocks = fn->blocks.count;

    for (IrBlockId p = 0; p < original_blocks; p++) {
      IrBlock* pre = &fn->blocks.data[p];

      if (pre->terminator.type != IR_TERMINATOR_JUMP)
        continue;

      IrBlockId h = pre->terminator.value.jump_target;
      IrBlock* head = &fn->blocks.data[h];

      if (p == h || optimizer_loop_edge_count(fn, h) != 2)
        continue;

      if (optimizer_loop_unswitch_range_direction(ctx, fid, p, h)) {
        grow_loop_uses(ctx, fn->value_count);
        continue;
      }

      IrBlockId test_id = h;

      if (head->terminator.type == IR_TERMINATOR_JUMP) {
        test_id = head->terminator.value.jump_target;
        if (test_id == p || test_id == h ||
            optimizer_loop_edge_count(fn, test_id) != 1)
          continue;
      }

      IrBlock* condition = &fn->blocks.data[test_id];

      if (condition->terminator.type != IR_TERMINATOR_CONDITIONAL)
        continue;

      IrBlockId b = condition->terminator.value.conditional_target.true_target;
      IrBlockId exit =
          condition->terminator.value.conditional_target.false_target;

      if (b == p || b == h || b == test_id || exit == p || exit == h ||
          exit == test_id || exit == b || optimizer_loop_edge_count(fn, b) != 1)
        continue;

      IrBlock* body = &fn->blocks.data[b];

      if (test_id == h && optimizer_loop_jumps_to(body, h)) {
        // AI generated by: Codex (GPT-6.2-sol)
        // Prompt: "Implement. You can change IR if it improves the
        // results/makes things more clear. Also try to split long files (300+)
        // into smaller thematic ones, like optimizer was before" Changes: Try
        // counted-loop simplification before invariant hoisting.
        if (optimizer_loop_pair_dynamic_while(ctx, fid, p, h, b)) {
          grow_loop_uses(ctx, fn->value_count);
          continue;
        }

        IrBlockId latch = optimizer_loop_split_counted_while(ctx, fid, h, b);

        if (latch != IR_INVALID_ID) {
          if (optimizer_loop_unroll_range(ctx, fid, p, h, h, b, latch))
            grow_loop_uses(ctx, fn->value_count);
        } else {
          IrBlock* blocks[] = {head, body};
          optimizer_loop_hoist_simple_loop(ctx, fn, pre, blocks, 2);
        }

        continue;
      }

      for (IrBlockId l = 0; l < fn->blocks.count; l++) {
        if (l == p || l == h || l == b || l == test_id || l == exit ||
            !optimizer_loop_jumps_to(&fn->blocks.data[l], h))
          continue;

        if (optimizer_loop_unroll_range(ctx, fid, p, h, test_id, b, l)) {
          grow_loop_uses(ctx, fn->value_count);
          break;
        }

        if (optimizer_loop_edge_count(fn, l) == 1 &&
            optimizer_loop_jumps_to(body, l)) {
          IrBlock* blocks[] = {head, condition, body, &fn->blocks.data[l]};
          optimizer_loop_hoist_simple_loop(ctx, fn, pre,
                                           blocks + (head == condition),
                                           head == condition ? 3 : 4);
        }
      }
    }
  }
}
